    private record Fixture(Merchant merchant,User student,String token,FileAssetEntity file,LinkedHashMap<String,Object> body){}
    private Fixture fixture()throws Exception{
        var m=merchant("PRINT");var u=user("STUDENT");var t=login(u);var f=row(data(upload(t,"虚构材料.pdf","application/pdf",pdf)));var b=body(m,f.getId().toString());b.put("expectedPriceVersion","7");b.put("expectedPayableAmount",200L);return new Fixture(m,u,t,f,b);
    }
    private HttpResponse<String> create(Fixture f,String key)throws Exception{return create(f.token(),f.body(),key);}
    private HttpResponse<String> create(String token,Object body,String key)throws Exception{
        var r=request("/api/v1/orders/prints",token).header("Content-Type","application/json");if(key!=null){r.header("Idempotency-Key",key);}return http.send(r.POST(HttpRequest.BodyPublishers.ofString(body instanceof String?(String)body:json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
    }
    private HttpResponse<String> cancel(Fixture f,String id)throws Exception{return call("POST","/api/v1/orders/"+id+"/cancel",null,f.token());}
    private Map<String,Object> fileFact(Fixture f){return jdbc.queryForMap("SELECT * FROM file_asset WHERE id=?",f.file().getId());}
    private void expiryAt(Fixture f,Instant t){jdbc.update("UPDATE file_asset SET expires_at=? WHERE id=?",FileRules.utc(t),f.file().getId());}
    private void retained(Fixture f,Instant t){assertThat(files.selectById(f.file().getId()).getExpiresAt()).isEqualTo(t==null?null:FileRules.utc(t));}
    private void noOrders(Fixture f,Map<String,Object> before){assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM service_order WHERE student_id=?",Long.class,f.student().id())).isZero();assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM idempotency_record WHERE account_id=?",Long.class,f.student().id())).isZero();assertThat(fileFact(f)).isEqualTo(before);}

    private HttpResponse<String> pay(Fixture f,String id)throws Exception{return call("POST","/api/v1/orders/"+id+"/payments/mock",null,f.token());}
    private JsonNode detail(Fixture f,String id)throws Exception{return data(call("GET","/api/v1/orders/"+id,null,f.token()));}
    private long count(String table,String id){return jdbc.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE order_id=?",Long.class,id);}
    private Map<String,Object> facts(Fixture f,String id){return Map.of("order",jdbc.queryForMap("SELECT * FROM service_order WHERE id=?",id),"print",jdbc.queryForMap("SELECT * FROM print_detail WHERE order_id=?",id),"file",fileFact(f),"events",jdbc.queryForList("SELECT * FROM order_event WHERE order_id=? ORDER BY event_seq",id),"payment",jdbc.queryForList("SELECT * FROM payment_record WHERE order_id=?",id),"refund",jdbc.queryForList("SELECT * FROM refund_record WHERE order_id=?",id));}
    private String order(Fixture f)throws Exception{return data(create(f,"pay-test")).path("id").asString();}
    private void assertPaid(Fixture f,String id)throws Exception{var o=detail(f,id);assertThat(o.path("status").asString()).isEqualTo("PENDING_ACCEPTANCE");assertThat(o.path("paymentStatus").asString()).isEqualTo("PAID");assertThat(o.path("printing").path("progress").asString()).isEqualTo("QUEUED");assertThat(o.path("refund").isNull()).isTrue();assertThat(count("payment_record",id)).isEqualTo(1);assertThat(count("refund_record",id)).isZero();retained(f,null);}
    private void assertRefunded(Fixture f,String id,String reason,Instant at)throws Exception{var o=detail(f,id);assertThat(o.path("status").asString()).isEqualTo("CLOSED");assertThat(o.path("paymentStatus").asString()).isEqualTo("REFUNDED");assertThat(o.path("closeReason").asString()).isEqualTo(reason);assertThat(o.path("printing").path("progress").asString()).isEqualTo("ABORTED");assertThat(o.path("payment").path("amount")).isEqualTo(o.path("refund").path("amount"));assertThat(count("payment_record",id)).isEqualTo(1);assertThat(count("refund_record",id)).isEqualTo(1);assertThat(count("order_event",id)).isEqualTo(3);if(at!=null){retained(f,at.plus(Duration.ofDays(7)));}}



    private HttpResponse<String> action(String token,String id,String suffix,String body)throws Exception{return call("POST","/api/v1/merchant/orders/"+id+"/"+suffix,body,token);}
    private HttpResponse<String> start(String token,String id)throws Exception{return action(token,id,"start",null);}
    private HttpResponse<String> ready(String token,String id)throws Exception{return action(token,id,"ready-for-pickup",null);}
    private String accepted(Fixture f)throws Exception{var id=order(f);data(pay(f,id));data(action(login(f.merchant().user()),id,"accept",null));return id;}
    private HttpResponse<byte[]> download(Fixture f,String token)throws Exception{return http.send(request("/api/v1/files/"+f.file().getId()+"/content",token).GET().build(),HttpResponse.BodyHandlers.ofByteArray());}
    private void pdf(Fixture f,String token)throws Exception{var response=download(f,token);assertThat(response.statusCode()).as(new String(response.body(),StandardCharsets.UTF_8)).isEqualTo(200);assertThat(response.body()).isEqualTo(pdf);}

    private String waiting(Fixture f)throws Exception{var id=accepted(f);var t=login(f.merchant().user());data(start(t,id));data(ready(t,id));return id;}
    private HttpResponse<String> pickup(Fixture f,String id)throws Exception{return pickup(f.token(),id,null);}
    private HttpResponse<String> pickup(String token,String id,String body)throws Exception{return call("POST","/api/v1/orders/"+id+"/pickup",body,token);}

    private record Done(Fixture f,String id,String student,String merchant,boolean booking,long barber){}
    private static final Instant BOOK_START=NOW.plusSeconds(9000);
    private Done done(String type)throws Exception{return stage(type,true);}
    private Done stage(String type,boolean completed)throws Exception{
        var f=fixture();if(type.equals("PRINT")){var id=waiting(f);if(completed){data(pickup(f,id));}return new Done(f,id,f.token(),login(f.merchant().user()),false,0);}
        var m=merchant("HAIRCUT");var person=new BarberEntity();person.setShopId(m.shop());person.setDisplayName("虚构评价理发师");person.setEnabled(true);person.setVersion(0L);barberRows.insert(person);bindingRows.insert(person.getId(),m.service());var date=NOW.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate();scheduleRows.insertGuard(person.getId(),date);scheduleRows.insert(person.getId(),date,FileRules.utc(NOW),FileRules.utc(NOW.plusSeconds(28800)));
        var b=json.writeValueAsString(Map.of("serviceId",Long.toString(m.service()),"barberId",person.getId().toString(),"startAt",BOOK_START.toString(),"expectedServiceVersion","5","expectedPayableAmount",99));
        var request=request("/api/v1/orders/bookings",f.token()).header("Content-Type","application/json").header("Idempotency-Key","review-booking");var id=data(http.send(request.POST(HttpRequest.BodyPublishers.ofString(b)).build(),HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8))).path("id").asString();data(pay(f,id));var mt=login(m.user());data(action(mt,id,"accept",null));fixed(BOOK_START);var st=login(f.student());mt=login(m.user());data(start(mt,id));if(completed){data(action(mt,id,"complete",null));}f=new Fixture(m,f.student(),st,f.file(),f.body());return new Done(f,id,st,mt,true,person.getId());
    }
    private HttpResponse<String> review(String token,String id,String body)throws Exception{return call("POST","/api/v1/orders/"+id+"/review",body,token);}
    private HttpResponse<String> review(Done d,int rating,String content)throws Exception{return review(d.student(),d.id(),json.writeValueAsString(Map.of("rating",rating,"content",content)));}
    private HttpResponse<String> ownReview(String token,String id)throws Exception{return call("GET","/api/v1/orders/"+id+"/review",null,token);}
    private Map<String,Object> life(Done d){var f=d.f();return Map.of("order",jdbc.queryForMap("SELECT * FROM service_order WHERE id=?",d.id()),"detail",jdbc.queryForMap(d.booking()?"SELECT * FROM booking_detail WHERE order_id=?":"SELECT * FROM print_detail WHERE order_id=?",d.id()),"file",fileFact(f),"events",jdbc.queryForList("SELECT * FROM order_event WHERE order_id=? ORDER BY event_seq",d.id()),"payment",jdbc.queryForList("SELECT * FROM payment_record WHERE order_id=?",d.id()),"refund",jdbc.queryForList("SELECT * FROM refund_record WHERE order_id=?",d.id()));}
    private long reviewCount(String id){return jdbc.queryForObject("SELECT COUNT(*) FROM order_review WHERE order_id=?",Long.class,id);}
    @ParameterizedTest @ValueSource(strings={"BOOKING","PRINT"})
    void actualCompletedOrdersCanBeReviewedOnceWithConsistentHistoryAndIndependentLifecycle(String type)throws Exception{
        var d=done(type);assertThat(detail(d.f(),d.id()).path("reviewed").asBoolean()).isFalse();expect(ownReview(d.student(),d.id()),404,"RESOURCE_NOT_FOUND");var before=life(d);var response=review(d,5,"  完成顺利😀\n内部换行保留  ");assertThat(response.statusCode()).as(response.body()).isEqualTo(201);var row=data(response);assertThat(row.propertyNames()).containsExactlyInAnyOrder("id","orderId","rating","content","visibility","createdAt");assertThat(row.path("content").asString()).isEqualTo("完成顺利😀\n内部换行保留");assertThat(row.path("orderId").asString()).isEqualTo(d.id());assertThat(row.path("visibility").asString()).isEqualTo("VISIBLE");assertThat(row.path("createdAt").asString()).isEqualTo((d.booking()?BOOK_START:NOW).toString());assertThat(data(ownReview(d.student(),d.id()))).isEqualTo(row);assertThat(reviewCount(d.id())).isEqualTo(1);assertThat(life(d)).isEqualTo(before);
        for(var pair:List.of(new String[]{"/api/v1/orders/",d.student()},new String[]{"/api/v1/merchant/orders/",d.merchant()},new String[]{"/api/v1/admin/orders/",login(user("ADMIN"))})){assertThat(data(call("GET",pair[0]+d.id(),null,pair[1])).path("reviewed").asBoolean()).isTrue();}
        assertThat(data(start(d.merchant(),d.id())).path("reviewed").asBoolean()).isTrue();assertThat(data(action(d.merchant(),d.id(),d.booking()?"complete":"ready-for-pickup",null)).path("reviewed").asBoolean()).isTrue();if(!d.booking()){assertThat(data(create(d.f(),"pay-test")).path("reviewed").asBoolean()).isTrue();}
        expect(review(d,5,"完成顺利😀\n内部换行保留"),409,"REVIEW_ALREADY_EXISTS");expect(review(d,1,"另一内容"),409,"REVIEW_ALREADY_EXISTS");assertThat(data(ownReview(d.student(),d.id()))).isEqualTo(row);assertThat(life(d)).isEqualTo(before);var db=jdbc.queryForMap("SELECT student_id,shop_id FROM order_review WHERE order_id=?",d.id());assertThat(((Number)db.get("student_id")).longValue()).isEqualTo(d.f().student().id());assertThat(((Number)db.get("shop_id")).longValue()).isEqualTo(d.f().merchant().shop());
    }
    @ParameterizedTest @ValueSource(strings={"ANONYMOUS","INVALID","MERCHANT","ADMIN","OTHER","DISABLED","REVOKED","EXPIRED"})
    void currentStudentIdentityAndOwnershipApplyToBothEntrypoints(String kind)throws Exception{var d=done("PRINT");String token=d.student();int status=403;String code="ROLE_FORBIDDEN";switch(kind){case "ANONYMOUS"->{token=null;status=401;code="AUTH_REQUIRED";}case "INVALID"->{token="invalid";status=401;code="TOKEN_INVALID";}case "MERCHANT","ADMIN"->token=login(user(kind));case "OTHER"->{token=login(user("STUDENT"));status=404;code="RESOURCE_NOT_FOUND";}case "DISABLED"->{invalidate(d.f().student(),kind);code="ACCOUNT_DISABLED";}case "REVOKED","EXPIRED"->{invalidate(d.f().student(),kind);status=401;code=kind.equals("REVOKED")?"SESSION_REVOKED":"SESSION_EXPIRED";}}var before=life(d);expect(review(token,d.id(),"{\"rating\":5,\"content\":\"正常\"}"),status,code);expect(ownReview(token,d.id()),status,code);assertThat(reviewCount(d.id())).isZero();assertThat(life(d)).isEqualTo(before);}
    @ParameterizedTest @ValueSource(strings={"0","01","-1","+1","x","9223372036854775808","9223372036854775807"})
    void idsAreCanonicalAndMissingIsHidden(String id)throws Exception{var f=fixture();int status=id.equals("9223372036854775807")?404:400;String code=status==404?"RESOURCE_NOT_FOUND":"VALIDATION_FAILED";expect(review(f.token(),id,"{\"rating\":5,\"content\":\"正常\"}"),status,code);expect(ownReview(f.token(),id),status,code);}
    @ParameterizedTest @ValueSource(strings={"null","{}","[]","{\"rating\":5}","{\"content\":\"正常\"}","{\"rating\":null,\"content\":\"正常\"}","{\"rating\":\"5\",\"content\":\"正常\"}","{\"rating\":true,\"content\":\"正常\"}","{\"rating\":5.0,\"content\":\"正常\"}","{\"rating\":1e0,\"content\":\"正常\"}","{\"rating\":0,\"content\":\"正常\"}","{\"rating\":6,\"content\":\"正常\"}","{\"rating\":5,\"content\":null}","{\"rating\":5,\"content\":1}","{\"rating\":5,\"content\":\"  \",\"shopId\":\"1\"}","{\"rating\":5,\"content\":\"正常\",\"visibility\":\"VISIBLE\"}","{\"rating\":5,\"content\":\"正常\",\"studentId\":\"1\"}"})
    void strictJsonCannotWriteOrEditThroughDuplicateRequests(String body)throws Exception{var d=done("PRINT");var before=life(d);expect(review(d.student(),d.id(),body),400,"VALIDATION_FAILED");assertThat(reviewCount(d.id())).isZero();data(review(d,5,"正常"));var row=data(ownReview(d.student(),d.id()));expect(review(d.student(),d.id(),body),400,"VALIDATION_FAILED");assertThat(data(ownReview(d.student(),d.id()))).isEqualTo(row);assertThat(life(d)).isEqualTo(before);}
    @ParameterizedTest @CsvSource({"1,1","5,1000","5,1001","1,0"})
    void unicodeCodepointAndRatingBoundaries(int rating,int size)throws Exception{var d=done("PRINT");var value="😀".repeat(size);var response=review(d,rating," \t"+value+"\n ");if(size==0||size>1000){expect(response,400,"VALIDATION_FAILED");assertThat(reviewCount(d.id())).isZero();}else{assertThat(response.statusCode()).isEqualTo(201);assertThat(data(response).path("content").asString()).isEqualTo(value);assertThat(jdbc.queryForObject("SELECT CHAR_LENGTH(content) FROM order_review WHERE order_id=?",Integer.class,d.id())).isEqualTo(size);}}
    @ParameterizedTest @ValueSource(strings={"UNPAID","AWAITING","ACCEPTED","PRINTING","READY","CLOSED"})
    void cannotReviewUnfinishedOrRefundedPrintButCanQueryItsAbsentReview(String stage)throws Exception{var f=fixture();var id=order(f);if(!stage.equals("UNPAID")){data(pay(f,id));}if(stage.equals("CLOSED")){data(cancel(f,id));}else if(!Set.of("UNPAID","AWAITING").contains(stage)){var mt=login(f.merchant().user());data(action(mt,id,"accept",null));if(!stage.equals("ACCEPTED")){data(start(mt,id));if(stage.equals("READY")){data(ready(mt,id));}}}var before=facts(f,id);expect(review(f.token(),id,"{\"rating\":5,\"content\":\"正常\"}"),409,"REVIEW_NOT_ALLOWED");expect(ownReview(f.token(),id),404,"RESOURCE_NOT_FOUND");assertThat(facts(f,id)).isEqualTo(before);}
    @ParameterizedTest @ValueSource(strings={"BOOKING","PRINT"})
    void hiddenRecordStillExistsForOwnerAndPreventsReposting(String type)throws Exception{var d=done(type);var original=data(review(d,4,"本人保留内容"));jdbc.update("UPDATE order_review SET visibility='HIDDEN' WHERE order_id=?",d.id());var before=life(d);var hidden=data(ownReview(d.student(),d.id()));assertThat(hidden.path("visibility").asString()).isEqualTo("HIDDEN");assertThat(hidden.path("content")).isEqualTo(original.path("content"));assertThat(detail(d.f(),d.id()).path("reviewed").asBoolean()).isTrue();expect(review(d,1,"替换"),409,"REVIEW_ALREADY_EXISTS");assertThat(life(d)).isEqualTo(before);}
    @ParameterizedTest @ValueSource(strings={"SHOP","MERCHANT","OWNER","SERVICE","PRICE","MOCK_OFF","FILE_EXPIRED"})
    void salesEligibilityAndFilesDoNotAffectCompletedOrderReview(String kind)throws Exception{var d=done("PRINT");switch(kind){case "SHOP"->jdbc.update("UPDATE shop SET approval_status='SUSPENDED',business_enabled=0 WHERE id=?",d.f().merchant().shop());case "MERCHANT"->jdbc.update("UPDATE account SET status='DISABLED' WHERE id=?",d.f().merchant().user().id());case "OWNER"->jdbc.update("UPDATE shop_member SET status='DISABLED' WHERE shop_id=?",d.f().merchant().shop());case "SERVICE"->jdbc.update("UPDATE service_item SET enabled=0 WHERE id=?",d.f().merchant().service());case "PRICE"->jdbc.update("UPDATE print_price_rule SET enabled=0 WHERE service_id=?",d.f().merchant().service());case "MOCK_OFF"->doReturn(false).when(mockPayment).enabled();case "FILE_EXPIRED"->{fixed(NOW.plus(Duration.ofDays(30)));cleanup.runOnce();assertThat(files.selectById(d.f().file().getId()).getStatus()).isEqualTo("DELETED");d=new Done(d.f(),d.id(),login(d.f().student()),d.merchant(),false,0);}}data(review(d,5,"合法历史"));data(ownReview(d.student(),d.id()));}
    @ParameterizedTest @ValueSource(longs={-1,0,1})
    void creationClockCannotPrecedeCompletion(long delta)throws Exception{fixed(NOW.minusSeconds(60));var f=fixture();var id=waiting(f);fixed(NOW);data(pickup(f,id));var d=new Done(f,id,f.token(),login(f.merchant().user()),false,0);var before=life(d);fixed(NOW.plusMillis(delta));var response=review(d,5,"时间边界");expect(response,delta<0?409:201,delta<0?"REVIEW_NOT_ALLOWED":"OK");if(delta<0){assertThat(reviewCount(id)).isZero();}else{assertThat(data(response).path("createdAt").asString()).isEqualTo(NOW.plusMillis(delta).toString());}assertThat(life(d)).isEqualTo(before);}
    @ParameterizedTest @ValueSource(strings={"NO_COMPLETED","NOT_PAID","NO_STARTED","WRONG_PROGRESS","NO_READY","WRONG_PICKED","MISSING_PAYMENT","PAYMENT_AMOUNT","PAYMENT_TIME"})
    void invalidCompletedFactsNeverBecomeReviewEligibility(String kind)throws Exception{var d=done("PRINT");switch(kind){case "NO_COMPLETED"->jdbc.update("UPDATE service_order SET completed_at=NULL WHERE id=?",d.id());case "NOT_PAID"->jdbc.update("UPDATE service_order SET payment_status='NOT_PAID' WHERE id=?",d.id());case "NO_STARTED"->jdbc.update("UPDATE service_order SET started_at=NULL WHERE id=?",d.id());case "WRONG_PROGRESS"->jdbc.update("UPDATE print_detail SET progress='READY_FOR_PICKUP' WHERE order_id=?",d.id());case "NO_READY"->jdbc.update("UPDATE print_detail SET ready_at=NULL WHERE order_id=?",d.id());case "WRONG_PICKED"->jdbc.update("UPDATE print_detail SET picked_up_at=? WHERE order_id=?",FileRules.utc(NOW.plusMillis(1)),d.id());case "MISSING_PAYMENT"->doReturn(null).when(money).payment(eq(Long.parseLong(d.id())));case "PAYMENT_AMOUNT"->jdbc.update("UPDATE payment_record SET amount=amount+1 WHERE order_id=?",d.id());case "PAYMENT_TIME"->jdbc.update("UPDATE payment_record SET paid_at=? WHERE order_id=?",FileRules.utc(NOW.minusMillis(1)),d.id());}var before=life(d);var response=review(d,5,"正常");assertThat(response.statusCode()).isEqualTo(kind.contains("PAYMENT")?500:409);assertThat(reviewCount(d.id())).isZero();assertThat(life(d)).isEqualTo(before);}
