    @ParameterizedTest @ValueSource(strings={"INSERT","SESSION","TRANSIENT","UNRELATED_DUPLICATE"})
    void insertOrFinalSessionFailureRollsBackOnlyReviewWithoutChangingOrder(String kind)throws Exception{var d=done("PRINT");var before=life(d);switch(kind){case "INSERT"->doThrow(new IllegalStateException("injected")).when(reviews).insert(any(com.campuslife.order.entity.OrderReviewEntity.class));case "SESSION"->{var real=sqlSession.getMapper(com.campuslife.order.mapper.OrderReviewMapper.class);doAnswer(i->{int n=real.insert((com.campuslife.order.entity.OrderReviewEntity)i.getArgument(0));fixed(NOW.plusSeconds(7200));return n;}).when(reviews).insert(any(com.campuslife.order.entity.OrderReviewEntity.class));}case "TRANSIENT"->doThrow(new org.springframework.dao.CannotAcquireLockException("injected")).when(reviews).insert(any(com.campuslife.order.entity.OrderReviewEntity.class));case "UNRELATED_DUPLICATE"->doThrow(new org.springframework.dao.DuplicateKeyException("injected",new java.sql.SQLException("Duplicate entry for key unrelated_index","23000",1062))).when(reviews).insert(any(com.campuslife.order.entity.OrderReviewEntity.class));}var response=review(d,5,"正常");expect(response,kind.equals("SESSION")?401:kind.equals("TRANSIENT")?503:500,kind.equals("SESSION")?"SESSION_EXPIRED":kind.equals("TRANSIENT")?"SERVICE_TEMPORARILY_UNAVAILABLE":"INTERNAL_ERROR");assertThat(reviewCount(d.id())).isZero();assertThat(life(d)).isEqualTo(before);}
