    @ParameterizedTest @ValueSource(strings={"SAME","DIFFERENT"})
    void realMysqlConcurrentSubmissionsCreateExactlyOneRow(String kind)throws Exception{var d=done("PRINT");var before=life(d);var gate=new CountDownLatch(1);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var one=pool.submit(()->{await(gate);return review(d,5,"原评价");});var two=pool.submit(()->{await(gate);return review(d,kind.equals("SAME")?5:1,kind.equals("SAME")?"原评价":"另一评价");});gate.countDown();var a=one.get(20,TimeUnit.SECONDS);var b=two.get(20,TimeUnit.SECONDS);assertThat(List.of(a.statusCode(),b.statusCode())).containsExactlyInAnyOrder(201,409);}assertThat(reviewCount(d.id())).isEqualTo(1);assertThat(life(d)).isEqualTo(before);}
