    @ParameterizedTest @ValueSource(strings={"SHOP","ORDER"})
    void realLockWaitChoosesCurrentOrderAndCreationInstant(String target)throws Exception{var d=done("PRINT");var held=new CountDownLatch(1);var release=new CountDownLatch(1);var entering=new CountDownLatch(1);var tx=new TransactionTemplate(manager);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var holder=pool.submit(()->tx.execute(s->{jdbc.queryForList(target.equals("SHOP")?"SELECT id FROM shop WHERE id=? FOR UPDATE":"SELECT id FROM service_order WHERE id=? FOR UPDATE",target.equals("SHOP")?d.f().merchant().shop():Long.parseLong(d.id()));held.countDown();await(release);return null;}));await(held);var real=sqlSession.getMapper(com.campuslife.order.mapper.OrderMapper.class);if(target.equals("SHOP")){doAnswer(i->{entering.countDown();return real.shareShop(i.getArgument(0));}).when(orderRows).shareShop(eq(d.f().merchant().shop()));}else{doAnswer(i->{entering.countDown();return real.lock(i.getArgument(0));}).when(orderRows).lock(eq(Long.parseLong(d.id())));}var request=pool.submit(()->review(d,5,"等待后时间"));await(entering);fixed(NOW.plusSeconds(10));release.countDown();holder.get(10,TimeUnit.SECONDS);assertThat(data(request.get(15,TimeUnit.SECONDS)).path("createdAt").asString()).isEqualTo(NOW.plusSeconds(10).toString());}finally{release.countDown();}}
    @ParameterizedTest @ValueSource(strings={"PRINT","BOOKING"})
    void noFileDateMerchantOrInstanceLocksAndNoIoAreNeeded(String type)throws Exception{var d=done(type);var f=d.f();var held=new CountDownLatch(1);var release=new CountDownLatch(1);var guard=storage.lock(f.file().getStorageKey());guard.lock();var tx=new TransactionTemplate(manager);clearInvocations(disk,files,scheduleRows);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var holder=pool.submit(()->tx.execute(s->{jdbc.queryForList("SELECT id FROM account WHERE id=? FOR UPDATE",f.merchant().user().id());jdbc.queryForList("SELECT id FROM file_asset WHERE id=? FOR UPDATE",f.file().getId());if(d.booking()){jdbc.queryForList("SELECT barber_id FROM barber_day_guard WHERE barber_id=? AND service_date=? FOR UPDATE",d.barber(),NOW.atZone(ZoneId.of("Asia/Shanghai")).toLocalDate());}held.countDown();await(release);return null;}));await(held);data(pool.submit(()->review(d,5,"不需要资源锁")).get(5,TimeUnit.SECONDS));verify(disk,never()).lock(anyString());verify(disk,never()).open(anyString(),anyString(),anyLong());verify(files,never()).lock(anyLong());verify(scheduleRows,never()).lockGuard(anyLong(),any());release.countDown();holder.get(10,TimeUnit.SECONDS);}finally{release.countDown();guard.unlock();}}
    @Test void ownerReadUsesOneSnapshotAndDoesNotBlockConcurrentInsert()throws Exception{var d=done("PRINT");var reached=new CountDownLatch(1);var release=new CountDownLatch(1);var real=sqlSession.getMapper(com.campuslife.order.mapper.OrderReviewMapper.class);doAnswer(i->{reached.countDown();await(release);return real.findByOrder(i.getArgument(0));}).when(reviews).findByOrder(eq(Long.parseLong(d.id())));try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var reading=pool.submit(()->ownReview(d.student(),d.id()));await(reached);data(pool.submit(()->review(d,5,"新评价")).get(5,TimeUnit.SECONDS));release.countDown();expect(reading.get(15,TimeUnit.SECONDS),404,"RESOURCE_NOT_FOUND");}finally{release.countDown();}reset(reviews);data(ownReview(d.student(),d.id()));}
    @Test void orderDetailReviewedFollowsItsOwnSnapshot()throws Exception{var d=done("PRINT");var reached=new CountDownLatch(1);var release=new CountDownLatch(1);var once=new java.util.concurrent.atomic.AtomicBoolean();var real=sqlSession.getMapper(com.campuslife.order.mapper.OrderReviewMapper.class);doAnswer(i->{if(once.compareAndSet(false,true)){reached.countDown();await(release);}return real.existsByOrder(i.getArgument(0));}).when(reviews).existsByOrder(eq(Long.parseLong(d.id())));try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var reading=pool.submit(()->detail(d.f(),d.id()));await(reached);data(pool.submit(()->review(d,5,"新评价")).get(5,TimeUnit.SECONDS));release.countDown();assertThat(reading.get(15,TimeUnit.SECONDS).path("reviewed").asBoolean()).isFalse();}finally{release.countDown();}assertThat(detail(d.f(),d.id()).path("reviewed").asBoolean()).isTrue();}
